import sys
from collections import defaultdict

def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)

def process_shift(in_time, out_time):
    in_min = minutes(in_time)
    out_min = minutes(out_time)
    worked = out_min - in_min

    if worked < 0:
        worked += 24 * 60

    if worked > 6 * 60:
        if worked > 9 * 60:
            worked -= 45
        else:
            worked -= 30

    return worked

def main():
    employee_data = defaultdict(int)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        parts = line.split()
        if len(parts) != 3:
            continue

        name, in_time, out_time = parts
        worked_hours = process_shift(in_time, out_time)
        employee_data[name] += worked_hours

    for name in sorted(employee_data.keys()):
        total_minutes = employee_data[name]
        hours = total_minutes // 60
        minutes = total_minutes % 60
        print(f"{name} {hours}:{minutes:02d}")


if __name__ == "__main__":
    main()
